using System;
using System.IO;
using System.Linq;
using System.Drawing;
using System.Reflection;
using System.Threading;
using System.Windows.Forms;
using LibrarySearch;
class CustomerFlowTests {
 static int checks;
 static object Get(object o,string n){return o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}
 static void Set(object o,string n,object v){o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).SetValue(o,v);}
 static object Call(object o,string n,params object[] a){return o.GetType().GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).Invoke(o,a);}
 static void Click(object o){Call(o,"OnClick",EventArgs.Empty);Application.DoEvents();}
 static void Check(bool ok,string name){if(!ok)throw new Exception(name);Console.WriteLine("PASS "+name);checks++;}
 static void Wait(Func<bool> done){var end=DateTime.UtcNow.AddSeconds(10);while(!done()){if(DateTime.UtcNow>end)throw new Exception("UI wait timed out");Application.DoEvents();Thread.Sleep(5);}Application.DoEvents();}
 static void Save(Control c,string path){c.PerformLayout();Application.DoEvents();using(var b=new Bitmap(c.Width,c.Height)){c.DrawToBitmap(b,new Rectangle(Point.Empty,c.Size));b.Save(path);}}
 static Control Page(object host){return ((Control)Get(host,"body")).Controls[0];}
 static System.Collections.Generic.IEnumerable<Control> All(Control c){yield return c;foreach(Control child in c.Controls)foreach(var nested in All(child))yield return nested;}
 [STAThread] static int Main(string[] args){try{
  Application.SetUnhandledExceptionMode(UnhandledExceptionMode.ThrowException);Application.EnableVisualStyles();Control.CheckForIllegalCrossThreadCalls=true;string output=Path.GetFullPath(args[0]);Directory.CreateDirectory(output);
  using(var form=new Form{ShowInTaskbar=false,StartPosition=FormStartPosition.Manual,Location=new Point(-20000,-20000),ClientSize=new Size(340,650)})using(var panel=new LibraryPanel(args[1],new UserSettings{LibraryRoot=Path.Combine(output,"isolated-library"),UsageNoticeVersion=1})){
   form.Controls.Add(panel);form.Show();((System.Windows.Forms.Timer)Get(panel,"updateTimer")).Stop();Wait(()=>(bool)Get(panel,"loaded")&&!(bool)Get(panel,"busy"));var host=(Control)Get(panel,"pageHost");var view=(Control)Get(panel,"modelResults");var query=(TextBox)Get(panel,"query");var rows=(ListView)Get(view,"rows");int uiThread=Thread.CurrentThread.ManagedThreadId;bool wrongThread=false;view.GetType().GetEvent("RunningChanged").AddEventHandler(view,new Action<bool>(b=>wrongThread|=Thread.CurrentThread.ManagedThreadId!=uiThread));
   string searched="";Set(view,"SearchProvider",new Func<string,int,CancellationToken,ModelSearchPage>((q,p,t)=>{searched=q;return new ModelSearchPage{Page=p,Total=23,Items=new[]{new ModelCandidate{Code="C7473159",Model="TP4057-MS",Manufacturer="YONGYUTAI",Package="SOT-23-6",HasLibrary=true},new ModelCandidate{Code="C2",Model="OTHER",Manufacturer="BRAND",Package="SOT-23",HasLibrary=false}}};}));
   query.Text="TP4057";Call(panel,"SearchRequested",false,false,null);Wait(()=>!(bool)Get(view,"running"));Check(view.Visible&&rows.Items.Count==2,"model search uses primary panel");
   query.Text="C7473159";Call(panel,"SearchRequested",false,false,null);Wait(()=>!(bool)Get(view,"running"));Check(searched=="C7473159"&&view.Visible,"C number follows identical search flow");
   Check(!All(view).Any(c=>c.Text.Contains("可尝试")||c.Text.Contains("候选")||c.Text.Contains("获取所选")),"no internal candidate or acquisition language");Check(((Control)Get(view,"fetch")).Text=="放置符号","direct placement action");
   Call(view,"Search","TP4057",2);Wait(()=>!(bool)Get(view,"running"));Check(((ModelSearchPage)Get(view,"current")).Page==2,"embedded pagination");
   query.Text="TP4057";Call(panel,"SearchRequested",false,false,null);Wait(()=>!(bool)Get(view,"running"));
   int placed=0;LibraryRecord last=null;panel.PlaceRequested+=r=>{placed++;last=r;};Set(panel,"FetchOverride",new Func<string,CancellationToken,FetchResult>((code,token)=>{token.ThrowIfCancellationRequested();var package=new LibraryPackage{DescriptionVersion="product-cn-1",AcquisitionVersion=ReleaseInfo.Acquisition,PinGeometryVersion="svg-line-1",Model3dStatus="unavailable"};return new FetchResult{Records=new[]{new LibraryRecord{Code=code,Name="TP4057-MS",Kind="Symbol",Description="充电管理芯片",RelatedName="SOT-23-6",LibraryRoot=panel.LibraryRoot,FilePath=Path.Combine(output,"mock.SchLib"),Package=package},new LibraryRecord{Code=code,Name="SOT-23-6",Kind="Footprint",Description="SOT-23-6",RelatedName="TP4057-MS",LibraryRoot=panel.LibraryRoot,FilePath=Path.Combine(output,"mock.PcbLib"),Package=package}}};}));
   rows.Items[0].Selected=true;rows.Items[0].Focused=true;Wait(()=>((Control)Get(view,"fetch")).Enabled);Click(Get(view,"fetch"));Wait(()=>placed==1&&!(bool)Get(panel,"busy"));Check(last.Kind=="Symbol"&&last.Code=="C7473159","one action fetches and requests symbol placement");Check(query.Text=="TP4057","model query remains visible after acquisition by internal C code");
   Call(panel,"RefetchCurrentComponent");Wait(()=>!(bool)Get(panel,"busy"));Check(query.Text=="TP4057"&&((LibraryRecord[])Get(panel,"online"))[0].Code=="C7473159","refetch uses selected C code without changing model query");
   Set(panel,"filter",2);query.Text="TP4057";Call(panel,"SearchRequested",false,false,null);Wait(()=>!(bool)Get(view,"running"));Check(((Control)Get(view,"fetch")).Text=="放置封装","footprint filter selects direct placement kind");rows.Items[0].Selected=true;Wait(()=>((Control)Get(view,"fetch")).Enabled);Click(Get(view,"fetch"));Wait(()=>placed==2);Check(last.Kind=="Footprint","one action requests footprint placement");
   int contexts=0;panel.PlacementContext=kind=>++contexts==1?"original-document":"changed-document";query.Text="C7473159";Call(panel,"SearchRequested",false,false,null);Wait(()=>!(bool)Get(view,"running"));rows.Items[0].Selected=true;Wait(()=>((Control)Get(view,"fetch")).Enabled);Click(Get(view,"fetch"));Wait(()=>!(bool)Get(panel,"busy"));Check(placed==2&&host.Visible,"changing target document prevents automatic placement");Call(host,"ClosePage");panel.PlacementContext=null;
   Set(panel,"FetchOverride",new Func<string,CancellationToken,FetchResult>((code,t)=>{t.WaitHandle.WaitOne();t.ThrowIfCancellationRequested();return null;}));query.Text="C7473159";Call(panel,"SearchRequested",false,false,null);Wait(()=>!(bool)Get(view,"running"));rows.Items[0].Selected=true;Wait(()=>((Control)Get(view,"fetch")).Enabled);Click(Get(view,"fetch"));Check((bool)Get(panel,"busy"),"component acquisition runs in background");Click(Get(panel,"cancel"));Wait(()=>!(bool)Get(panel,"busy"));Check(placed==2,"cancelled acquisition cannot place on the canvas");
   Set(view,"SearchProvider",new Func<string,int,CancellationToken,ModelSearchPage>((q,p,t)=>{t.WaitHandle.WaitOne();t.ThrowIfCancellationRequested();return null;}));query.Text="乐鑫";Call(panel,"SearchRequested",false,false,null);Check(rows.Enabled&&((Control)Get(view,"loading")).Visible,"loading never disables native list");Save(panel,Path.Combine(output,"search-loading.png"));using(var image=new Bitmap(view.Width,view.Height)){view.DrawToBitmap(image,new Rectangle(Point.Empty,view.Size));Color pixel=image.GetPixel(image.Width/2,image.Height/3);Check(pixel.R<80&&pixel.G<80&&pixel.B<80,"loading surface remains dark");}Click(Get(panel,"cancel"));Wait(()=>!(bool)Get(view,"running"));Check(placed==2,"cancelled search does not place");Check(!wrongThread,"all UI completion events stay on UI thread");
   Call(panel,"ShowUsageNotice",true);Check(host.Visible&&!(Page(host) is Form)&&Application.OpenForms.Count==1,"first-use notice is embedded");foreach(var size in new[]{new Size(280,520),new Size(340,650),new Size(420,780)}){form.ClientSize=size;Application.DoEvents();Check(host.Bounds==panel.ClientRectangle,"notice bounded at "+size.Width);Save(panel,Path.Combine(output,"notice-"+size.Width+".png"));}Call(host,"ClosePage");
   Call(panel,"ShowMore");Check(host.Visible&&Page(host).GetType().Name=="SettingsPage"&&Application.OpenForms.Count==1,"settings remains inside AD panel");for(int i=0;i<4;i++){Call(Page(host),"ShowSection",i);form.ClientSize=new Size(340,650);Save(panel,Path.Combine(output,"settings-"+i+".png"));Check(!All(Page(host)).Any(c=>c.Text.Contains("测试")||c.Text.Contains("SDK")||c.Text.Contains("宿主")),"customer settings copy "+i);}Call(host,"ClosePage");Check(!host.Visible,"back restores original search surface");
   Call(panel,"ChooseAppearance");Check(Page(host).GetType().Name=="AppearancePage"&&Application.OpenForms.Count==1,"appearance editor is embedded without window icon");foreach(var size in new[]{new Size(280,520),new Size(340,650),new Size(420,780)}){form.ClientSize=size;Save(panel,Path.Combine(output,"appearance-"+size.Width+".png"));Check(host.Bounds==panel.ClientRectangle,"appearance bounded at "+size.Width);}var appearance=Page(host);Check(((SymbolAppearance)Call(appearance,"Read")).Mode=="Classic","default symbol style retained");((NumericUpDown)Get(appearance,"nameSize")).Value=9;Check(((SymbolAppearance)Call(appearance,"Read")).Mode=="Custom","editing style becomes custom without disabling fields");Call(host,"ClosePage");Check(Page(host).GetType().Name=="SettingsPage","appearance back returns to settings");Call(host,"ClosePage");
   Set(panel,"availableUpdate",new WebsiteRelease{Version="0.6.1-dev.99",Date="2026-10-26",Channel="beta",Size=2000,Notes="改进使用体验。"});Call(panel,"ShowAvailableUpdate");Check(Page(host).GetType().Name=="UpdatePage"&&Application.OpenForms.Count==1,"update details are embedded");Save(panel,Path.Combine(output,"update.png"));Call(host,"ClosePage");Call(host,"ClosePage");form.Close();
  }Console.WriteLine(checks+" checks passed");return 0;
 }catch(Exception error){Console.Error.WriteLine(error);return 1;}}
}
